const fs = require("node:fs");
const path = require("node:path");
const root = path.resolve(__dirname, "..");
const leafletRoot = path.dirname(require.resolve("leaflet/package.json"));
const js = fs.readFileSync(path.join(leafletRoot, "dist/leaflet.js"), "utf8")
  .replace(/\/\/# sourceMappingURL=.*$/m, "");
const css = fs.readFileSync(path.join(leafletRoot, "dist/leaflet.css"), "utf8")
  .replace(/url\(images\/([^\)]+)\)/g, (_, name) =>
    `url(data:image/png;base64,${fs.readFileSync(path.join(leafletRoot, "dist/images", name)).toString("base64")})`);
const runtime = fs.readFileSync(path.join(root, "map/runtime.js"), "utf8").replace(/\r\n/g, "\n");
const license = fs.readFileSync(path.join(leafletRoot, "LICENSE"), "utf8");
const html = `<!doctype html><html lang="ru"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1,user-scalable=no">
<style>${css}
html,body,#map{height:100%;width:100%;margin:0}body{font-family:Arial,sans-serif}
.traffic-marker{background:transparent;border:0}.traffic-dot{display:block;box-sizing:border-box;width:23px;height:23px;border:3px solid white;border-radius:50%;box-shadow:0 1px 5px #0008}
.traffic-dot-selected{outline:3px solid #111827;outline-offset:2px}
#tile-notice{position:absolute;z-index:1000;top:8px;left:52px;right:8px;max-width:380px;background:#fff;padding:10px;border:1px solid #a00000;border-radius:6px;font-size:13px;color:#8b0000}
#retry-tiles{display:block;margin-top:6px;padding:7px;background:#fff;border:1px solid #999;border-radius:4px;color:#111}
</style></head><body><div id="map" aria-label="Карта Москвы"></div>
<div id="tile-notice" role="alert" hidden>Не удалось загрузить часть карты. Проверьте интернет.<button id="retry-tiles">Повторить загрузку карты</button></div>
<script>${js.replace(/<\/script/gi, "<\\/script")}</script>
<script>${runtime.replace(/<\/script/gi, "<\\/script")}</script></body></html>`;
fs.writeFileSync(path.join(root, "map/mapDocument.js"),
  `// Generated by npm run build:map. Leaflet license is in LEAFLET-LICENSE.txt.\nexport const MAP_HTML = ${JSON.stringify(html)};\n`);
fs.writeFileSync(path.join(root, "map/LEAFLET-LICENSE.txt"), license);
console.log("Карта собрана: Leaflet, стили и служебные изображения включены в приложение.");
